-- Base recipe library seed (idempotent). Generated by scripts/seed-base-recipes.mjs.
with v(name,slug,meal_slot,instructions,tags,image_url) as (values
  ('Tortilla de claras con espinacas y aguacate','tortilla-claras-espinacas-aguacate','desayuno','Bate el huevo con las claras y salpimienta. Saltea las espinacas en una sarten antiadherente y vierte el huevo, cuajando la tortilla a fuego medio. Tuesta el pan integral y cubrelo con el aguacate aplastado. Sirve la tortilla junto a la tostada.',ARRAY['alta-proteina','definicion','vegetariana','sin-lactosa']::text[],'/seed/recipes/tortilla-claras-espinacas-aguacate.webp'),
  ('Porridge de avena con whey y platano','porridge-avena-whey-platano','desayuno','Cuece la avena con la leche desnatada a fuego medio removiendo hasta espesar. Retira del fuego, deja templar un minuto e incorpora la proteina whey hasta integrar. Corona con el platano en rodajas y la mantequilla de cacahuete derretida por encima.',ARRAY['alta-proteina','volumen','vegetariana']::text[],'/seed/recipes/porridge-avena-whey-platano.webp'),
  ('Bowl de yogur griego con frutos rojos','bowl-yogur-griego-frutos-rojos','desayuno','Pon el yogur griego en un bol y alisa la superficie. Reparte por encima los frutos rojos y la avena en copos. Espolvorea las almendras troceadas y termina con un hilo de miel.',ARRAY['alta-proteina','definicion','vegetariana']::text[],'/seed/recipes/bowl-yogur-griego-frutos-rojos.webp'),
  ('Tortitas de avena y proteina','tortitas-avena-proteina','desayuno','Tritura la avena con la proteina, el huevo, las claras y el platano hasta lograr una masa homogenea. Cuaja pequenas tortitas en una sarten antiadherente a fuego medio, dorando por ambos lados. Apila las tortitas y corona con los frutos rojos.',ARRAY['alta-proteina','volumen','vegetariana']::text[],'/seed/recipes/tortitas-avena-proteina.webp'),
  ('Tostada de requeson con pavo y tomate','tostada-requeson-pavo-tomate','desayuno','Tuesta el pan integral hasta que quede crujiente. Unta el requeson sobre la tostada y riega con un hilo de aceite de oliva. Cubre con las lonchas de pavo y las rodajas de tomate, y salpimienta al gusto.',ARRAY['alta-proteina','definicion']::text[],'/seed/recipes/tostada-requeson-pavo-tomate.webp'),
  ('Pollo con arroz integral y brocoli','pollo-arroz-integral-brocoli','comida','Cocina el arroz integral segun el paquete y reserva. Saltea la pechuga de pollo troceada con la mitad del aceite hasta dorar, salpimenta. Anade el pimiento y el brocoli al wok y saltea 4-5 minutos hasta que queden tiernos pero crujientes. Sirve el pollo y las verduras sobre el arroz y riega con el aceite restante.',ARRAY['alta-proteina','definicion','sin-gluten','sin-lactosa']::text[],'/seed/recipes/pollo-arroz-integral-brocoli.webp'),
  ('Salmon al horno con boniato y espinacas','salmon-horno-boniato-espinacas','comida','Hornea el lomo de salmon a 200C durante 12-14 minutos con un poco de sal. Asa el boniato cortado en dados con la mitad del aceite hasta que este tierno. Saltea las espinacas con el aceite restante hasta que reduzcan. Emplata el salmon sobre las espinacas y el boniato, y exprime la naranja por encima a modo de alino.',ARRAY['alta-proteina','sin-gluten','sin-lactosa','omega-3']::text[],'/seed/recipes/salmon-horno-boniato-espinacas.webp'),
  ('Ternera magra con patata y pimientos','ternera-magra-patata-pimientos','comida','Cuece la patata en dados hasta que este tierna y reserva. Sella la ternera magra en una sarten bien caliente con la mitad del aceite, salpimenta y reserva jugosa. En la misma sarten saltea el pimiento y el tomate con el aceite restante. Mezcla la ternera con las verduras y la patata, y sirve caliente.',ARRAY['alta-proteina','volumen','sin-gluten','sin-lactosa']::text[],'/seed/recipes/ternera-magra-patata-pimientos.webp'),
  ('Bowl de lentejas y quinoa con aguacate','bowl-lentejas-quinoa-aguacate','comida','Cuece la quinoa y escurrela bien. Calienta las lentejas cocidas y mezclalas con la quinoa en un bol. Incorpora el tomate y las espinacas troceados en crudo. Corona con el aguacate en laminas, riega con el aceite de oliva y sazona al gusto.',ARRAY['alta-proteina','vegana','vegetariana','sin-gluten','sin-lactosa']::text[],'/seed/recipes/bowl-lentejas-quinoa-aguacate.webp'),
  ('Pasta con atun y calabacin','pasta-atun-calabacin','comida','Cuece la pasta al dente y escurrela. Saltea el calabacin en dados con el aceite de oliva hasta que este tierno. Anade el tomate troceado y cocina 2-3 minutos para hacer una salsa ligera. Incorpora el atun escurrido y la pasta, mezcla bien y sirve caliente.',ARRAY['alta-proteina','definicion','sin-lactosa']::text[],'/seed/recipes/pasta-atun-calabacin.webp'),
  ('Merluza al horno con patata y brocoli','merluza-al-horno-con-patata-y-brocoli','cena','Precalienta el horno a 200C y coloca la merluza con rodajas de tomate y un hilo de aceite de oliva. Hornea 12-15 minutos hasta que el pescado se desmenuce. Cuece la patata y el brocoli al vapor 8-10 minutos. Sirve todo junto y termina con sal y pimienta.',ARRAY['alta-proteina','definicion','sin-gluten','sin-lactosa']::text[],'/seed/recipes/merluza-al-horno-con-patata-y-brocoli.webp'),
  ('Salmon con quinoa y espinacas','salmon-con-quinoa-y-espinacas','cena','Salpimienta el salmon y marcalo en una sarten con unas gotas de aceite, 3-4 minutos por cada lado. Saltea las espinacas en la misma sarten hasta que reduzcan. Sirve sobre la quinoa cocida caliente y acompana con gajos de naranja para refrescar.',ARRAY['alta-proteina','sin-gluten','sin-lactosa','omega-3']::text[],'/seed/recipes/salmon-con-quinoa-y-espinacas.webp'),
  ('Gambas salteadas con calabacin y arroz integral','gambas-salteadas-con-calabacin-y-arroz-integral','cena','Calienta el aceite en un wok y saltea el calabacin y el pimiento en dados a fuego fuerte 4-5 minutos. Anade las gambas y el tomate troceado y saltea 3 minutos mas hasta que las gambas esten rosadas. Incorpora el arroz integral cocido, mezcla bien y sirve caliente.',ARRAY['alta-proteina','definicion','sin-gluten','sin-lactosa']::text[],'/seed/recipes/gambas-salteadas-con-calabacin-y-arroz-integral.webp'),
  ('Tortilla de claras con espinacas y queso fresco','tortilla-de-claras-con-espinacas-y-queso-fresco','cena','Bate el huevo entero con las claras y salpimienta. Saltea las espinacas en una sarten antiadherente hasta que reduzcan, anade el batido y cuaja la tortilla a fuego medio. Reparte el queso fresco batido por encima y dobla. Acompana con una rebanada de pan integral tostado.',ARRAY['alta-proteina','vegetariana','definicion']::text[],'/seed/recipes/tortilla-de-claras-con-espinacas-y-queso-fresco.webp'),
  ('Pechuga de pavo con lentejas y pimiento','pechuga-de-pavo-con-lentejas-y-pimiento','cena','Salpimienta la pechuga de pavo y hazla a la plancha con la mitad del aceite 4-5 minutos por lado, luego cortala en tiras. Saltea el pimiento en dados con el aceite restante y anade el tomate troceado 3 minutos. Incorpora las lentejas cocidas, calienta un par de minutos y sirve el pavo encima.',ARRAY['alta-proteina','definicion','sin-gluten','sin-lactosa']::text[],'/seed/recipes/pechuga-de-pavo-con-lentejas-y-pimiento.webp'),
  ('Bowl de yogur griego con frutos rojos y almendras','bowl-yogur-griego-frutos-rojos-almendras','snack','Vierte el yogur griego en un bol. Reparte por encima los frutos rojos y las almendras laminadas. Riega con un hilo de miel y sirve frio.',ARRAY['alta-proteina','vegetariana','sin-gluten']::text[],'/seed/recipes/bowl-yogur-griego-frutos-rojos-almendras.webp'),
  ('Batido de proteina, platano y cacahuete','batido-proteina-platano-cacahuete','snack','Pela el platano y trocealo. Anade la leche desnatada, la proteina whey y la mantequilla de cacahuete. Tritura hasta obtener una textura cremosa y sirve al momento.',ARRAY['alta-proteina','vegetariana','sin-gluten','volumen']::text[],'/seed/recipes/batido-proteina-platano-cacahuete.webp'),
  ('Manzana con crema de cacahuete y nueces','manzana-crema-cacahuete-nueces','snack','Lava la manzana y cortala en gajos. Unta cada gajo con mantequilla de cacahuete. Espolvorea las nueces troceadas por encima y sirve.',ARRAY['vegetariana','vegana','sin-gluten','sin-lactosa']::text[],'/seed/recipes/manzana-crema-cacahuete-nueces.webp'),
  ('Bol de requeson con naranja y miel','bol-requeson-naranja-miel','snack','Pon el requeson en un bol. Pela la naranja, separala en gajos y colocala encima. Termina con un hilo de miel y sirve frio.',ARRAY['alta-proteina','vegetariana','sin-gluten','definicion']::text[],'/seed/recipes/bol-requeson-naranja-miel.webp'),
  ('Bocaditos de avena y proteina','bocaditos-avena-proteina','snack','Mezcla la avena con la proteina whey y la mantequilla de cacahuete. Anade la miel y un poco de agua hasta lograr una masa moldeable. Forma bolitas y refrigera 30 minutos antes de servir.',ARRAY['alta-proteina','vegetariana','volumen']::text[],'/seed/recipes/bocaditos-avena-proteina.webp')
)
insert into public.recipes (name,slug,meal_slot,instructions,tags,image_url,is_base_library,workspace_id)
select v.name,v.slug,v.meal_slot,v.instructions,v.tags,v.image_url,true,null
from v
where not exists (select 1 from public.recipes r where r.slug = v.slug);

